def score_stencil(X,Y,mask,maxshift=5):
 v=(X==0); y=(Y==3); R,C=X.shape; rows=[]
 for dr in range(-maxshift,maxshift+1):
  for dc in range(-maxshift,maxshift+1):
   for source in [0,5]:
    vals=np.zeros(X.shape,dtype=int)
    for rr0,cc0 in mask:
     rr=np.arange(R)[:,None]+dr+rr0; cc=np.arange(C)[None,:]+dc+cc0
     rr=np.broadcast_to(rr,(R,C)); cc=np.broadcast_to(cc,(R,C)); good=(rr>=0)&(rr<R)&(cc>=0)&(cc<C)
     tmp=np.zeros(X.shape,int); tmp[good]=(X[rr[good],cc[good]]==source); vals+=tmp
    for mod in [0,1]:
     pred=(vals%2==mod)&v
     acc=np.mean(pred[v]==y[v]); rows.append((acc,dr,dc,source,mod, np.sum(pred&y),np.sum(pred&~y&v),np.sum(~pred&y&v)))
 return sorted(rows,reverse=True)
