def shift_corr(X,Y,maxrad=10):
 R,C=X.shape; valid=(X==0); yy=(Y==3); rows=[]
 for dr in range(-maxrad,maxrad+1):
  for dc in range(-maxrad,maxrad+1):
   for val in [0,5]:
    src=np.zeros(X.shape,dtype=bool)
    for r in range(R):
     for c in range(C):
      rr,cc=r+dr,c+dc
      if 0<=rr<R and 0<=cc<C: src[r,c]=(X[rr,cc]==val)
    pred=src&valid
    rows.append((np.mean(pred[valid]==yy[valid]),dr,dc,val))
 return sorted(rows,reverse=True)
