def transform_pts(pts,rot,flip):
 p=np.array(pts,dtype=int)
 if flip: p[:,1]*=-1
 for _ in range(rot): p=np.stack([-p[:,1],p[:,0]],axis=1)
 p-=p.min(axis=0)
 return [tuple(x) for x in p]
