def stencil_threshold(X,Y,mask,maxshift=4,target=3,src=5):
 R,C=X.shape; valid=X==0; y=Y==target; out=[]
 for dr in range(-maxshift,maxshift+1):
  for dc in range(-maxshift,maxshift+1):
   z=np.zeros((R,C),dtype=int)
   for ro,co in mask:
    rr=np.arange(R)[:,None]+dr+ro; cc=np.arange(C)[None,:]+dc+co
    rr=np.broadcast_to(rr,(R,C));cc=np.broadcast_to(cc,(R,C)); good=(rr>=0)&(rr<R)&(cc>=0)&(cc<C)
    tmp=np.zeros((R,C),bool);tmp[good]=X[rr[good],cc[good]]==src;z+=tmp
   for t in range(1,len(mask)+1):
    for op in ['>=','<=','=']:
     pred=(z>=t if op=='>=' else z<=t if op=='<=' else z==t)&valid
     acc=np.mean(pred[valid]==y[valid]);out.append((acc,dr,dc,src,t,op,int((pred&y).sum()),int((pred&~y&valid).sum()),int((~pred&y).sum())))
 return sorted(out,reverse=True)
